selector_to_html = {"a[href=\"#pyskyfire.common.rotation.CLOCKWISE\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.rotation.CLOCKWISE\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.rotation.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CLOCKWISE</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'clockwise'</span></span></dt><dd></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.common.rotation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.rotation<a class=\"headerlink\" href=\"#module-pyskyfire.common.rotation\" title=\"Link to this heading\">\u00b6</a></h1><p>Sense of rotation about a component\u2019s own axis.</p><p>An impeller spins one way about its shaft and the volute around it must wind\nthe same way, since a volute wound against the discharge swirl collects the\nflow backwards. Both state the sense with the same word here, so that a design\ncan be checked by reading it rather than by looking at a render.</p>", "a[href=\"#pyskyfire.common.rotation.rotation_sign\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.rotation.rotation_sign\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.rotation.</span></span><span class=\"sig-name descname\"><span class=\"pre\">rotation_sign</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">value</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p><code class=\"docutils literal notranslate\"><span class=\"pre\">+1.0</span></code> for a counterclockwise sense, <code class=\"docutils literal notranslate\"><span class=\"pre\">-1.0</span></code> for a clockwise one.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.rotation.COUNTERCLOCKWISE\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.rotation.COUNTERCLOCKWISE\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.rotation.</span></span><span class=\"sig-name descname\"><span class=\"pre\">COUNTERCLOCKWISE</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">'counterclockwise'</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.rotation.parse_rotation\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.rotation.parse_rotation\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.rotation.</span></span><span class=\"sig-name descname\"><span class=\"pre\">parse_rotation</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">value</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></span></dt><dd><p>Normalise a rotation sense to <a class=\"reference internal\" href=\"#pyskyfire.common.rotation.CLOCKWISE\" title=\"pyskyfire.common.rotation.CLOCKWISE\"><code class=\"xref py py-data docutils literal notranslate\"><span class=\"pre\">CLOCKWISE</span></code></a> or <a class=\"reference internal\" href=\"#pyskyfire.common.rotation.COUNTERCLOCKWISE\" title=\"pyskyfire.common.rotation.COUNTERCLOCKWISE\"><code class=\"xref py py-data docutils literal notranslate\"><span class=\"pre\">COUNTERCLOCKWISE</span></code></a>.</p><p>Accepts <code class=\"docutils literal notranslate\"><span class=\"pre\">'cw'</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">'clockwise'</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">'ccw'</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">'counterclockwise'</span></code>,\nin any capitalisation.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
